import streamlit as st
import streamlit.components.v1 as components
from pathlib import Path
import base64

st.set_page_config(page_title="RUNAWAY 3D", page_icon="🐎", layout="wide")
BASE = Path(__file__).parent

def read_b64(filename):
    path = BASE / filename
    return base64.b64encode(path.read_bytes()).decode("ascii") if path.exists() else ""

# Đặt An83.mp3 và thua.mp3 cùng thư mục nếu muốn dùng âm thanh.
